test("リソースのRGB色空間を選択して塗りの色を変更する", async () => {
  const result = await executeColorSpace({
    resources: "<< /ColorSpace << /CS1 /DeviceRGB >> >>",
    content: "/CS1 cs .2 .4 .6 sc",
  });
  assert(result.ok);
  const state = GraphicsStateStack.current(
    result.value.context.graphicsStateStack,
  );

  expect(state.fillColorSpace).toEqual(ColorSpace.deviceRGB());
  expect(state.fillColor).toEqual(Color.rgb(0.2, 0.4, 0.6));
  expect(result.value.warnings).toEqual([]);
});

test("CS と SCN は輪郭だけを変更し、q/Q は色空間と色を復元する", async () => {
  const result = await executeColorSpace({
    resources:
      "<< /ColorSpace << /Ink [/DeviceN [/Cyan /Magenta] /DeviceCMYK << /FunctionType 2 >>] >> >>",
    content: ".6 g /Ink CS .2 .8 SCN q /DeviceRGB CS .1 .2 .3 SC Q",
  });
  assert(result.ok);
  const state = GraphicsStateStack.current(
    result.value.context.graphicsStateStack,
  );

  expect(state.strokeColorSpace).toMatchObject({ family: "DeviceN" });
  expect(state.strokeColor).toMatchObject({
    kind: "components",
    components: [0.2, 0.8],
  });
  expect(state.fillColor).toEqual(Color.gray(0.6));
  expect(result.value.warnings).toEqual([]);
});

test.each([
  1, 3, 4,
])("ICCBased はプロファイルの間接参照 /N=%i を使う", async (count) => {
  const result = await executeColorSpace({
    resources: "<< /ColorSpace 1 0 R >>",
    objects: [
      "<< /ICC 2 0 R >>",
      "[/ICCBased 3 0 R]",
      "<< /N 4 0 R /Length 0 >>\nstream\n\nendstream",
      String(count),
    ],
    content: `/ICC cs ${Array.from({ length: count }, () => ".5").join(" ")} scn`,
  });
  assert(result.ok);
  const state = GraphicsStateStack.current(
    result.value.context.graphicsStateStack,
  );

  expect(ColorSpace.componentCount(state.fillColorSpace)).toEqual({
    some: true,
    value: count,
  });
  expect(result.value.warnings).toEqual([]);
});

test.each([
  ["sc", "cs"],
  ["SC", "CS"],
  ["scn", "cs"],
  ["SCN", "CS"],
])("%s は現在の色空間と成分数の過不足を検出する", async (operatorName, selection) => {
  const result = await executeColorSpace({
    resources: "<< >>",
    content: `/DeviceRGB ${selection} .1 .2 ${operatorName}`,
  });

  expect(result).toMatchObject({
    ok: false,
    error: {
      code: "OPERATOR_OPERAND_COUNT_MISMATCH",
      operatorName,
      required: 3,
      actual: 2,
    },
  });
});

test.each([
  "[/Future 1]",
  "[/Mystery 1 2]",
])("未知の族 %s は選択位置に警告し、成分数を不明にする", async (definition) => {
  const result = await executeColorSpace({
    resources: `<< /ColorSpace << /Odd ${definition} >> >>`,
    content: "/DeviceCMYK cs /Odd cs .2 .4 sc",
  });
  assert(result.ok);

  expect(
    ColorSpace.componentCount(
      GraphicsStateStack.current(result.value.context.graphicsStateStack)
        .fillColorSpace,
    ),
  ).toEqual({ some: false });
  expect(result.value.warnings).toMatchObject([
    { code: "COLOR_SPACE_UNSUPPORTED", offset: 20 },
  ]);
});

test.each([
  {
    label: "直接の別名",
    resources: "<< /ColorSpace << /Alias /Missing >> >>",
    objects: [],
  },
  {
    label: "間接参照の別名",
    resources: "<< /ColorSpace << /Alias 1 0 R >> >>",
    objects: ["/Missing"],
  },
  {
    label: "連鎖する別名",
    resources: "<< /ColorSpace << /Alias /Next /Next /Missing >> >>",
    objects: [],
  },
])("$label の参照先がない場合は名前不在を警告する", async ({
  resources,
  objects,
}) => {
  const result = await executeColorSpace({
    resources,
    objects,
    content: "/Alias cs .2 .4 sc",
  });
  assert(result.ok);
  const space = GraphicsStateStack.current(
    result.value.context.graphicsStateStack,
  ).fillColorSpace;

  expect(result.value.warnings).toEqual([
    {
      code: "COLOR_SPACE_NOT_FOUND",
      message: "Unresolved color space: /Missing",
      offset: 7,
    },
  ]);
  expect(space).toEqual({ family: "Unknown", name: "Missing" });
  expect(ColorSpace.componentCount(space)).toEqual({ some: false });
});

export type ColorSpace =
  | DeviceColorSpace
  | {
      readonly family: "CalGray" | "CalRGB" | "Lab" | "Separation";
      readonly definition: PdfArray;
    }
  | {
      readonly family: "ICCBased";
      readonly profile: PdfStream;
      readonly components: IccComponentCount;
    }
  | {
      readonly family: "Indexed";
      readonly base: ColorSpace;
      readonly definition: PdfArray;
    }
  | {
      readonly family: "DeviceN";
      readonly names: readonly string[];
      readonly definition: PdfArray;
    }
  | { readonly family: "Pattern"; readonly base: Option<ColorSpace> }
  | { readonly family: "Unknown"; readonly name: string };

componentCount(space: ColorSpace): Option<number> {
  if (typeof space === "string") {
    switch (space) {
      case "DeviceGray":
        return some(DeviceComponentCounts.Gray);
      case "DeviceRGB":
        return some(DeviceComponentCounts.RGB);
      case "DeviceCMYK":
        return some(DeviceComponentCounts.CMYK);
    }
  }

  switch (space.family) {
    case "CalGray":
    case "Separation":
    case "Indexed":
      return some(1);
    case "CalRGB":
    case "Lab":
      return some(DeviceComponentCounts.RGB);
    case "ICCBased":
      return some(space.components);
    case "DeviceN":
      return some(space.names.length);
    case "Pattern":
      return space.base.some
        ? ColorSpace.componentCount(space.base.value)
        : some(0);
    case "Unknown":
      return none;
  }

async fromResources(
  resources: PdfResources,
  resolveRef: ResolveRef,
): Promise<Result<ColorSpaceResources, PdfError>> {
  const category = await PdfResources.getCategory(
    resources,
    "ColorSpace",
    resolveRef,
  );
  if (!category.ok) {
    return category;
  }

  if (!category.value.some) {
    return ok(ColorSpaceResources.empty());
  }

  const dictionary = category.value.value;
  const spaces = new Map<string, Result<ColorSpaceDefinition, PdfError>>();
  for (const [name, value] of dictionary.entries) {
    spaces.set(
      name,
      await ColorSpaceDefinition.read(value, resolveRef, {
        dictionary,
        ancestors: new Set(),
      }),
    );
  }

  return ok({ spaces });

const next = { ...scope, ancestors: new Set([...scope.ancestors, object]) };
if (object.type === "name") {
  const builtin = ColorSpace.fromName(object.value);
  if (builtin.some) {
    return ok({ colorSpace: builtin.value, warnings: [] });
  }

  const local = scope.dictionary.entries.get(object.value);
  return local
    ? ColorSpaceDefinition.read(local, resolveRef, next)
    : ok(
        ColorSpaceDefinition.unresolved(
          object.value,
          "COLOR_SPACE_NOT_FOUND",
        ),
      );
}
